#include <stdio.h>

static volatile int idx = 7;
static int a[4] = {1, 2, 3, 4};

int main(void) {
    printf("v=%d\n", a[idx]);
    return 0;
}

fn main() {
    let v = vec![10, 20, 30, 40];
    let idx = std::hint::black_box(7usize);
    println!("{}", v[idx]);
}

#include <stdlib.h>

int main(void) {
    int *p = malloc(16);
    if (!p) return 2;
    free(p);
    return p[0];
}

fn main() {
    let mut v = Box::new(1i32);
    let p = &mut *v;
    drop(v);
    *p = 2;
}

