#include <stdlib.h>

int main(void) {
    int *p = malloc(16);
    if (!p) return 2;
    free(p);
    free(p);
    return 0;
}

fn main() {
    let v = Box::new(1i32);
    drop(v);
    drop(v);
}

#include <stdlib.h>

int main(void) {
    int *p = malloc(64);
    if (!p) return 2;
    free(p + 2);
    return 0;
}

fn free_it(owned: Box<i32>) { drop(owned); }

fn main() {
    let arr = [1i32, 2, 3];
    let p: *mut i32 = &arr[1] as *const i32 as *mut i32;
    free_it(p);
}

fn main() {
    let p: Option<&i32> = None;
    println!("{}", p.unwrap());
}

int main(void) {
    int x = 2147483647 + 1;
    return x;
}

fn main() {
    let a = std::hint::black_box(i32::MAX);
    let b = std::hint::black_box(1);
    println!("{}", a + b);
}

int main(void) {
    int x = 1 << 32;
    return x;
}

fn main() {
    let n = std::hint::black_box(32u32);
    println!("{}", 1i32 << n);
}
